WITH base AS (SELECT *, TRIM(category) clean_category FROM products WHERE supplier_id = 16 OR cost > 550), products_stats AS (SELECT supplier_id, ROUND(AVG(stock_qty), 2) avg_stock_qty, ROUND((100 * SUM(CASE WHEN brand = 'Acme' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_acme FROM base GROUP BY supplier_id) SELECT supplier_id, avg_stock_qty, pct_acme FROM products_stats WHERE pct_acme > 58 ORDER BY supplier_id, 2
